      const count = ed.propose(range, data.text);
      if (count === 0) {
        setNotice({ kind: "nothing" });
        setMode("idle");
        setReview(null);
        return;
      }
      setReview({ selection: target, history: [...history, { instruction, proposal: data.text }], changeCount: count });
