const { chromium } = require("/tmp/pw-chiri/node_modules/playwright-core");
const fs = require("fs");
(async () => {
  const browser = await chromium.launch({
    executablePath: "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
    headless: true,
  });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  const errors = [];
  page.on("pageerror", (e) => errors.push(e.message));
  await page.addInitScript(() => localStorage.setItem("coauthor.locale", "en-US"));
  await page.goto("http://localhost:3123/", { waitUntil: "networkidle" });
  await page.evaluate(() => localStorage.removeItem("coauthor.doc"));
  await page.reload({ waitUntil: "networkidle" });

  const read = async () => page.evaluate(() => ({
    lang: document.documentElement.lang,
    title: document.title,
    h1: document.querySelector("h1")?.textContent,
    tag: document.querySelector("header p")?.textContent,
    locale: document.querySelector("header select")?.value,
    buttons: [...document.querySelectorAll("header ~ div button, .border-b button")].map(b => b.textContent).slice(0, 8),
    footer: document.querySelector("footer")?.innerText,
    doc: document.querySelector(".cm-content")?.innerText?.slice(0, 40),
  }));

  const en = await read();
  const expect = (name, cond, extra) => { if (!cond) errors.push(name + " " + JSON.stringify(extra ?? "")); };

  expect("en lang", en.lang === "en-US", en);
  expect("en title", en.title === "Co-author", en);
  expect("en shorten", en.buttons.includes("Shorten"), en);

  async function pick(locale) {
    await page.locator("header select").selectOption(locale);
    await page.waitForTimeout(50);
    return read();
  }
  const pt = await pick("pt-BR");
  expect("pt lang", pt.lang === "pt-BR", pt);
  expect("pt h1", pt.h1 === "Coautor", pt);
  expect("pt shorten", pt.buttons.includes("Encurtar"), pt);
  expect("pt footer", pt.footer.includes("Modo simulado"), pt);
  expect("pt doc kept", pt.doc.startsWith("# Launch"), pt);

  const es = await pick("es-AR");
  expect("es shorten", es.buttons.includes("Acortar"), es);
  expect("es tag", es.tag.startsWith("Escribí"), es);

  const zh = await pick("zh-CN");
  expect("zh shorten", zh.buttons.includes("缩短"), zh);
  expect("zh h1", zh.h1 === "合著者", zh);
  expect("zh lang", zh.lang === "zh-CN", zh);

  await page.reload({ waitUntil: "networkidle" });
  const kept = await read();
  expect("persist zh", kept.locale === "zh-CN" && kept.h1 === "合著者", kept);

  // Suggestion in zh, then switch language while the diff is open.
  const selected = await page.evaluate(() => {
    const root = document.querySelector(".cm-content");
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    let node;
    while ((node = walker.nextNode())) {
      const i = node.textContent.indexOf("Right now a lot of new users");
      if (i >= 0) {
        const end = node.textContent.indexOf("what happens next.");
        const range = document.createRange();
        range.setStart(node, i);
        range.setEnd(node, end + "what happens next.".length);
        const sel = getSelection();
        sel.removeAllRanges();
        sel.addRange(range);
        return true;
      }
    }
    return false;
  });
  expect("selected", selected);
  await page.getByRole("button", { name: "缩短" }).click();
  await page.getByRole("button", { name: "全部接受" }).waitFor({ timeout: 15000 });
  const chunk = await page.locator('button[name="accept"]').first().textContent();
  expect("zh chunk", chunk === "接受", chunk);
  const beforeSwitch = await page.locator(".cm-content").innerText();
  await page.locator("header select").selectOption("pt-BR");
  await page.waitForTimeout(100);
  const chunkPt = await page.locator('button[name="accept"]').first().textContent();
  const barPt = await page.getByRole("button", { name: "Aceitar tudo" }).count();
  const afterSwitch = await page.locator(".cm-content").innerText();
  expect("chunk relabeled", chunkPt === "Aceitar", chunkPt);
  expect("bar relabeled", barPt === 1);
  expect("doc stable", beforeSwitch === afterSwitch);
  await page.getByRole("button", { name: "Aceitar tudo" }).click();
  await page.waitForTimeout(200);
  const accepted = await page.locator(".cm-content").innerText();
  expect("accepted changed", accepted !== afterSwitch && accepted.includes("many new users"));

  // API error code is translated, and follows a later language change.
  await page.route("**/api/suggest", (route) => route.fulfill({
    status: 400,
    contentType: "application/json",
    body: JSON.stringify({ error: "document_too_long" }),
  }));
  await page.getByRole("button", { name: "Encurtar" }).click();
  await page.getByText("O documento é longo demais").waitFor({ timeout: 10000 });
  await page.locator("header select").selectOption("es-AR");
  await page.getByText("demasiado largo").waitFor({ timeout: 5000 });
  await page.locator("header select").selectOption("en-US");
  await page.getByText("too long to edit").waitFor({ timeout: 5000 });

  await page.setViewportSize({ width: 390, height: 844 });
  await page.screenshot({ path: "/tmp/chiri-lang-mobile.png" });
  const mobileSelect = await page.locator("header select").isVisible();
  expect("mobile select", mobileSelect);
  await page.setViewportSize({ width: 1280, height: 900 });
  await page.locator("header select").selectOption("zh-CN");
  await page.screenshot({ path: "/tmp/chiri-lang-zh.png" });

  fs.writeFileSync("/tmp/chiri-lang.json", JSON.stringify({ errors, en, pt, es, zh }, null, 2));
  console.log(errors.length ? "FAIL\n" + errors.join("\n") : "OK");
  await browser.close();
  process.exit(errors.length ? 1 : 0);
})().catch((e) => { console.error(e); process.exit(1); });
